SELECT la.Nombre AS Laboratorio, SUM(l.Stock) AS StockTotal FROM Laboratorios la JOIN Medicamentos m ON la.IDLaboratorio = m.IDLaboratorio JOIN Lotes l ON l.IDMedicamento = m.IDMedicamento WHERE YEAR(l.Vencimiento) = 2025 AND m.IDMedicamento > 100 AND m.IDMedicamento < 500 GROUP BY la.Nombre HAVING SUM(l.Stock) < 200 ORDER BY StockTotal ASC LIMIT 5;
SELECT m.Nombre AS Medicamento, MAX(l.Stock) AS StockMaximo FROM Medicamentos m JOIN Lotes l ON m.IDMedicamento = l.IDMedicamento JOIN Laboratorios la ON m.IDLaboratorio = la.IDLaboratorio WHERE la.Nombre LIKE 'A%' OR la.Nombre LIKE 'B%' GROUP BY m.Nombre;
SELECT m.Nombre AS Medicamento, m.Precio AS PrecioVenta, l.Precio AS PrecioCosto, (m.Precio - l.Precio) AS margenGanancia FROM Medicamentos m JOIN Lotes l ON m.IDMedicamento = l.IDMedicamento ORDER BY MargenGanancia DESC;
SELECT COUNT(*) AS CantidadLotes FROM Lotes l JOIN Medicamentos m ON l.IDMedicamento = m.IDMedicamento WHERE l.Ubicacion = 'A-1' AND m.Monodroga LIKE '%Amoxi%';